/*
 * Held kymograph: renders the browser engine to a PNG where x = LED and y = time (top to
 * bottom), so pulse speed, spacing, overlap and event timing can be judged at a glance —
 * the same view as the strip under the 3D simulator, but for a whole scripted run.
 *
 *   node tools/held/kymo.js --out kymo.png --seconds 20 \
 *     --script '[[2,63],[8,"pieceOut"],[10,31]]' \   # [time, pieceMask] or [time, "eventName"]
 *     --params '{"heartbeat":{"pulseSpeed":[14,22]}}' \
 *     --strip '{"leds":120,"origin":0,"reps":1}' --every 2 --scale 4
 */
'use strict';
const fs = require('node:fs');
const zlib = require('node:zlib');
const HeldEngine = require('../../wled00/data/held/engine.js');

const args = process.argv.slice(2);
const opt = (name, def) => { const i = args.indexOf('--' + name); return i >= 0 && args[i + 1] !== undefined ? args[i + 1] : def; };
const OUT = opt('out', 'kymo.png');
const SECONDS = Number(opt('seconds', 20));
const SCRIPT = JSON.parse(opt('script', '[]'));
const FPS = 40;
const EVERY = Number(opt('every', 2));    // keep one row per N frames
const SCALE = Number(opt('scale', 4));    // horizontal pixels per LED

function png(w, h, rgb) {
  const raw = Buffer.alloc((w * 3 + 1) * h);
  for (let y = 0; y < h; y++) rgb.copy(raw, y * (w * 3 + 1) + 1, y * w * 3, (y + 1) * w * 3);
  const table = [];
  for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; table[n] = c >>> 0; }
  const crc = (b) => { let c = 0xffffffff; for (const x of b) c = table[(c ^ x) & 255] ^ (c >>> 8); return (c ^ 0xffffffff) >>> 0; };
  const chunk = (type, data) => {
    const len = Buffer.alloc(4); len.writeUInt32BE(data.length);
    const td = Buffer.concat([Buffer.from(type), data]);
    const c = Buffer.alloc(4); c.writeUInt32BE(crc(td));
    return Buffer.concat([len, td, c]);
  };
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(w, 0); ihdr.writeUInt32BE(h, 4); ihdr[8] = 8; ihdr[9] = 2;
  return Buffer.concat([Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]), chunk('IHDR', ihdr), chunk('IDAT', zlib.deflateSync(raw)), chunk('IEND', Buffer.alloc(0))]);
}

const e = new HeldEngine();
e.setStrips([JSON.parse(opt('strip', '{"leds":120}'))]);
e.setParams(JSON.parse(opt('params', '{}')));
const L = e.strips[0].leds, buf = new Float64Array(3 * L), rows = [];
let next = 0;
for (let f = 0; f < SECONDS * FPS; f++) {
  while (next < SCRIPT.length && SCRIPT[next][0] <= f / FPS) {
    const a = SCRIPT[next++][1];
    if (typeof a === 'string') e.trigger(a); else e.setPieces(a);
  }
  e.tick(1 / FPS);
  if (f % EVERY) continue;
  e.render(0, buf);
  const row = Buffer.alloc(L * SCALE * 3);
  for (let i = 0; i < L; i++) for (let s = 0; s < SCALE; s++) for (let c = 0; c < 3; c++) row[(i * SCALE + s) * 3 + c] = Math.round(buf[3 * i + c] * 255);
  if (f % FPS === 0) row.fill(255, 0, 3 * Math.min(SCALE, 2));   // one-second tick marks on the left edge
  rows.push(row);
}
fs.writeFileSync(OUT, png(L * SCALE, rows.length, Buffer.concat(rows)));
console.log(`wrote ${OUT}: ${L} LEDs x ${rows.length} rows (${(FPS / EVERY).toFixed(0)} rows/s)`);
// AI: end
